<script setup lang="ts">
import SoftSelect from '../components/SoftSelect.vue'
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import { api, post, query, time, contextVersion, isCancelled, businessDate } from '../lib/api'
import { selectedDate, campuses, currentCampusId, refreshCampuses } from '../lib/state'
import { openDialog, useResource, notify, label } from '../lib/ui'
import type { Attendance, BatchResult, ClassRoom, Student, Attachment } from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
import StatusBadge from '../components/StatusBadge.vue'
const classId=ref<string | number>(''); const keyword = ref(''); const status = ref(''); const selected = ref<number[]>([]); const results = ref<BatchResult['results']>([])
const attendanceCampusId=ref<string|number>(currentCampusId.value??(campuses.value.length===1?campuses.value[0]!.id:''))
watch(attendanceCampusId,()=>{selected.value=[];classId.value='';results.value=[]})
const photoBusy=ref(false),photoController=new AbortController();onBeforeUnmount(()=>photoController.abort())
const classes = useResource(()=>api<ClassRoom[]>('/classes'))
const {data,loading,error,refresh} = useResource(async()=>{await refreshCampuses();const [students,records] = await Promise.all([api<Student[]>(`/students${query({classId:classId.value})}`),api<Attendance[]>(`/attendance${query({date:selectedDate.value,classId:classId.value})}`)]);return students.map(student=>{const row=records.find(r=>r.studentId===student.id);return {studentId:student.id,campusId:student.campusId,studentName:student.name,className:student.className,campusName:student.campusName,date:selectedDate.value,status:row?.status||'NOT_ARRIVED',checkInTime:row?.checkInTime,checkOutTime:row?.checkOutTime,source:row?.source||'—'}})},[selectedDate,classId])
const rows = computed(()=>(data.value||[]).filter(s=>(!attendanceCampusId.value||String(s.campusId)===String(attendanceCampusId.value))&&(!keyword.value||s.studentName.includes(keyword.value))&&(!status.value||s.status===status.value)))
watch(data,()=>{selected.value=[]})
function selectAll(event:Event) {selected.value=(event.target as HTMLInputElement).checked?rows.value.map(s=>s.studentId):[]}
async function mark(kind:'check-in'|'check-out', ids=selected.value) {
  const chosen=[...ids]
  if(!chosen.length){notify('请先选择学生','error');return}
  const leave=kind==='check-out'
  const ok=await openDialog({title:leave?'确认学生离校':'确认到校签到',description:leave?`将为 ${chosen.length} 位学生登记 ${selectedDate.value} 离校。系统按当日有效排课与报名扣除课时；余额不足会保留待处理消课，请在课时账本跟进。`:`将为 ${chosen.length} 位学生登记 ${selectedDate.value} 到校。请核对学生已实际到校。重复签到不会重复创建。`,fields:leave&&selectedDate.value<new Date(Date.now()+8*3600000).toISOString().slice(0,10)?[{key:'historicalReason',label:'历史离校核对原因（仅校长或老板）',type:'textarea',required:true}]:[],confirm:leave?'确认离校并结算':'确认签到',submit:async v=>{const result=await post<BatchResult>(`/attendance/${kind}`,{studentIds:chosen,date:selectedDate.value,historicalReason:v.historicalReason||''});results.value=result.results;const success=result.results.filter(r=>r.success).length;notify(`${success} 位操作成功，${result.results.length-success} 位未成功`,success===result.results.length?'success':'error')}})
  if(ok) refresh()
}
async function photoMark(event:Event,row:{studentId:number;studentName:string;campusId?:number;status:string}){
 const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file||!row.campusId)return
 if(selectedDate.value!==businessDate()){notify('拍照考勤仅支持当天','error');return}const version=contextVersion.value;photoBusy.value=true
 try{const body=new FormData();body.append('file',file);const uploaded=await api<Attachment>('/files',{method:'POST',body,campusId:row.campusId,signal:photoController.signal});const result=await api<{message:string;notificationCount:number}>('/attendance/photo',{method:'POST',body:{studentId:row.studentId,photoFileId:uploaded.id,action:row.status==='PRESENT'?'CHECK_OUT':'CHECK_IN'},signal:photoController.signal});notify(`${result.message}，已为${result.notificationCount}位绑定家长生成站内消息`);await refresh()}catch(error){if(version===contextVersion.value&&!isCancelled(error))notify((error as Error).message,'error')}finally{if(version===contextVersion.value)photoBusy.value=false;input.value=''}
}
</script>
<template><PageHeader title="到校签到" subtitle="从到校到归家，每一刻都有安心守护。"><button class="btn secondary" :disabled="!selected.length" @click="mark('check-out')"><AppIcon name="LogOut" :size="17" />批量离校</button><button class="btn primary" :disabled="!selected.length" @click="mark('check-in')"><AppIcon name="ScanLine" :size="17" />批量签到 <span v-if="selected.length">{{ selected.length }}</span></button></PageHeader><div class="info-banner"><AppIcon name="Info" :size="18" /><span>业务日期：{{ selectedDate }}。请先在 <RouterLink to="/safety">安全接送</RouterLink> 核验授权，再确认实际离校。离校将触发课时结算；签到与消课支持重复请求，避免重复扣减。</span></div><section class="panel check-in-location"><AppIcon name="School" :size="22" /><div><strong>按校区筛选</strong><SoftSelect v-model="attendanceCampusId" aria-label="筛选校区" :options="[{value:'',label:'全部授权校区'},...campuses.filter(c=>c.enabled!==false&&(currentCampusId===null||c.id===currentCampusId)).map(c=>({value:c.id,label:c.name}))]" /><p>老师确认实际到校后登记，离校前核对授权与接送码。</p></div></section><section class="panel"><div class="filter-bar"><div class="search-input"><AppIcon name="Search" :size="17" /><input v-model="keyword" placeholder="搜索学生姓名" aria-label="搜索考勤学生" /></div><SoftSelect v-model="classId" aria-label="考勤班级" :options="[{value:'',label:'全部班级'}, ...(classes.data.value || []).filter(c=>!attendanceCampusId||String(c.campusId)===String(attendanceCampusId)).map(c => ({value:c.id,label:c.name}))]" /><SoftSelect v-model="status" aria-label="考勤状态" :options="[{value:'',label:'全部状态'},{value:'NOT_ARRIVED',label:'未到校'},{value:'PRESENT',label:'已到校'},{value:'LEFT',label:'已离校'},{value:'ON_LEAVE',label:'已请假'}]" /><span class="filter-count">已选 {{ selected.length }} 人</span><button class="icon-btn" aria-label="刷新考勤" @click="refresh"><AppIcon name="RefreshCw" :size="17" /></button></div><LoadState :loading="loading" :error="error" :empty="!rows.length" @retry="refresh"><div class="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="选择全部学生" :checked="!!rows.length&&selected.length===rows.length" @change="selectAll" /></th><th>学生</th><th>所属校区</th><th>班级</th><th>状态</th><th>到校时间</th><th>离校时间</th><th>签到来源</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.studentId"><td><input v-model="selected" type="checkbox" :value="row.studentId" :aria-label="`选择${row.studentName}`" /></td><td><div class="person"><span class="student-avatar" :class="`avatar-${index%4}`">{{ row.studentName.slice(-2) }}</span><strong>{{ row.studentName }}</strong></div></td><td>{{ row.campusName||'—' }}</td><td>{{ row.className }}</td><td><StatusBadge :value="row.status" /></td><td class="numeric">{{ time(row.checkInTime) }}</td><td class="numeric">{{ time(row.checkOutTime) }}</td><td>{{ row.source==='DEMO'?'演示签到':row.source==='MANUAL'?'人工签到':row.source==='LOCATION'?'定位签到':label(row.source) }}</td><td><label v-if="['NOT_ARRIVED','PRESENT'].includes(row.status)" class="text-btn photo-button">{{row.status==='PRESENT'?'拍照签退':'拍照签到'}}<input type="file" accept="image/*" capture="environment" :disabled="photoBusy" @change="photoMark($event,row)" /></label><button v-if="row.status==='NOT_ARRIVED'" class="text-btn" @click="mark('check-in',[row.studentId])">到校签到</button><button v-else-if="row.status==='PRESENT'" class="text-btn" @click="mark('check-out',[row.studentId])">登记离校</button><span v-else class="muted">{{row.status==='ON_LEAVE'?'整日请假不消课':'今日已离校'}}</span></td></tr></tbody></table></div></LoadState></section><section v-if="results.length" class="panel result-panel"><div class="panel-header"><h2>最近操作结果</h2><button class="icon-btn" aria-label="关闭操作结果" @click="results=[]"><AppIcon name="X" :size="17" /></button></div><div v-for="result in results" :key="result.studentId" class="result-row"><AppIcon :name="result.success?'CircleCheck':'CircleAlert'" :size="17" :class="result.success?'text-green':'text-danger'" /><strong>{{ data?.find(s=>s.studentId===result.studentId)?.studentName||`学生 #${result.studentId}` }}</strong><span>{{ result.message }}</span></div></section></template>

<style scoped>
.photo-button{display:inline-flex;cursor:pointer;margin-right:12px}.photo-button input{display:none}

.check-in-location{display:flex;align-items:flex-start;gap:14px;padding:22px;margin-bottom:20px;color:var(--accent)}.check-in-location>div{flex:1;min-width:0}.check-in-location strong{display:block;font-size:14px;color:var(--text)}.check-in-location .soft-select{width:100%;margin:12px 0}.check-in-location p{font-size:12px;line-height:1.8;color:var(--text-secondary)}
</style>
